def largestIsland(grid):
    rows, cols = len(grid), len(grid[0])
    label = [[0] * cols for _ in range(rows)]
    size = [0]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and label[r][c] == 0:
                ident = len(size)
                label[r][c] = ident
                stack = [(r, c)]
                count = 0
                while stack:
                    y, x = stack.pop()
                    count += 1
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] == 1 and label[ny][nx] == 0:
                            label[ny][nx] = ident
                            stack.append((ny, nx))
                size.append(count)
    best = max(size)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                ids = set()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = r + dy, c + dx
                    if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] == 1:
                        ids.add(label[ny][nx])
                best = max(best, 1 + sum(size[i] for i in ids))
    return best
